    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id BIGINT;
BEGIN
    INSERT INTO public.mv_refresh_log (view_name, status, triggered_by)
    VALUES (p_view_name, 'SUCCESS', COALESCE(p_triggered_by, 'pg_cron'))
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;


