--

CREATE FUNCTION public.fn_refresh_mv_realtime_kpis(p_triggered_by character varying DEFAULT 'pg_cron'::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_log_id BIGINT;
