CREATE FUNCTION public.fn_refresh_realtime_kpis() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_realtime_kpis;
    RAISE NOTICE '✅ mv_realtime_kpis atualizado em %', now();
END $$;


