--
-- Name: ml_features_daily_mv; Type: MATERIALIZED VIEW; Schema: public; Owner: admin
--

CREATE MATERIALIZED VIEW public.ml_features_daily_mv AS
 WITH td AS (
         SELECT locker_telemetry.locker_id,
            (date_trunc('day'::text, (locker_telemetry.occurred_at AT TIME ZONE 'UTC'::text)))::date AS feature_date,
            (avg(locker_telemetry.temperature_celsius))::numeric(10,4) AS temperature_mean,
            (avg(locker_telemetry.humidity_pct))::numeric(10,4) AS humidity_mean,
            (min(locker_telemetry.battery_pct))::numeric(10,2) AS battery_min,
            (count(*))::numeric AS tel_pts
           FROM public.locker_telemetry
          GROUP BY locker_telemetry.locker_id, ((date_trunc('day'::text, (locker_telemetry.occurred_at AT TIME ZONE 'UTC'::text)))::date)
        ), dd AS (
         SELECT l.id AS locker_id,
            (date_trunc('day'::text, (ds.updated_at AT TIME ZONE 'UTC'::text)))::date AS feature_date,
            count(*) FILTER (WHERE (upper((ds.state)::text) ~ similar_to_escape('%(FAIL|ERROR|FAULT|JAM|TAMPER|LOCK)%'::text))) AS door_fail_day
           FROM (public.door_state ds
             JOIN public.lockers l ON (((l.machine_id IS NOT NULL) AND ((l.machine_id)::text <> ''::text) AND ((l.machine_id)::text = (ds.machine_id)::text))))
          GROUP BY l.id, ((date_trunc('day'::text, (ds.updated_at AT TIME ZONE 'UTC'::text)))::date)
        ), sd AS (
         SELECT locker_slots.locker_id,
            (date_trunc('day'::text, (locker_slots.last_opened_at AT TIME ZONE 'UTC'::text)))::date AS feature_date,
            count(*) AS usage_day
           FROM public.locker_slots
          WHERE (locker_slots.last_opened_at IS NOT NULL)
          GROUP BY locker_slots.locker_id, ((date_trunc('day'::text, (locker_slots.last_opened_at AT TIME ZONE 'UTC'::text)))::date)
        ), keys AS (
         SELECT td.locker_id,
            td.feature_date
           FROM td
        UNION
         SELECT dd.locker_id,
            dd.feature_date
           FROM dd
        UNION
         SELECT sd.locker_id,
            sd.feature_date
           FROM sd
        ), base AS (
         SELECT k.locker_id,
            k.feature_date,
            COALESCE(td.temperature_mean, (0)::numeric) AS temperature_mean,
            COALESCE(td.humidity_mean, (0)::numeric) AS humidity_mean,
            COALESCE(td.battery_min, (0)::numeric) AS battery_min,
            COALESCE(dd.door_fail_day, (0)::bigint) AS door_fail_day,
            COALESCE(sd.usage_day, (0)::bigint) AS usage_day,
            COALESCE(td.tel_pts, (0)::numeric) AS tel_pts
           FROM (((keys k
             LEFT JOIN td ON ((((td.locker_id)::text = (k.locker_id)::text) AND (td.feature_date = k.feature_date))))
             LEFT JOIN dd ON ((((dd.locker_id)::text = (k.locker_id)::text) AND (dd.feature_date = k.feature_date))))
             LEFT JOIN sd ON ((((sd.locker_id)::text = (k.locker_id)::text) AND (sd.feature_date = k.feature_date))))
        ), rolled AS (
         SELECT base.locker_id,
            base.feature_date,
            base.temperature_mean,
            base.humidity_mean,
            base.battery_min,
            (sum(base.door_fail_day) OVER w7)::integer AS door_failures_7d,
            (sum(base.usage_day) OVER w7)::integer AS usage_events_7d,
            sum(
                CASE
                    WHEN (base.tel_pts > (0)::numeric) THEN LEAST((24)::numeric, (base.tel_pts / 8.0))
                    ELSE (0)::numeric
                END) OVER w7 AS uptime_hours_7d
           FROM base
          WINDOW w7 AS (PARTITION BY base.locker_id ORDER BY base.feature_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)
        )
 SELECT rolled.locker_id,
    rolled.feature_date,
    rolled.temperature_mean,
    rolled.humidity_mean,
    rolled.battery_min,
    rolled.door_failures_7d,
    rolled.usage_events_7d,
    rolled.uptime_hours_7d
   FROM rolled
  WITH NO DATA;


ALTER TABLE public.ml_features_daily_mv OWNER TO admin;

