    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    CONSTRAINT ck_seller_product_price CHECK ((price_cents > 0)),
    CONSTRAINT ck_seller_product_quantity CHECK ((quantity >= 0)),
    CONSTRAINT ck_seller_product_status CHECK (((status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text, ('OUT_OF_STOCK'::character varying)::text])))
);


