    CONSTRAINT ck_poeo_status CHECK (((status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('DELIVERED'::character varying)::text, ('FAILED'::character varying)::text, ('DEAD_LETTER'::character varying)::text, ('SKIPPED'::character varying)::text])))
